css:
@import url("https://fonts.googleapis.com/css2?family=Teko:wght@500;600;700&family=Work+Sans:wght@400;500;600&display=swap");
:root{--rb:#1D4ED8;--rb2:#1E3A8A;--yl:#FFC300;--cc:#ECECE8;--ink:#161B26;--gr:#575D69;--ln:#D8D8D2;--h:"Teko",Impact,sans-serif;--b:"Work Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.6;color:var(--ink);background:var(--cc)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:600;margin:0;line-height:.95;text-transform:uppercase;letter-spacing:.01em}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--yl);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--yl);outline-offset:2px}
.hd{background:var(--rb2);color:#fff}.nav{display:flex;justify-content:space-between;align-items:center;height:76px;position:relative}.logo{font-family:var(--h);font-size:32px;text-decoration:none;text-transform:uppercase}.logo span{color:var(--yl)}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:var(--yl)}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;font-size:20px;cursor:pointer}
.hero{background:var(--rb);color:#fff;position:relative;overflow:hidden}.hero:before{content:"";position:absolute;left:0;right:0;bottom:0;height:18px;background:repeating-linear-gradient(135deg,var(--yl) 0 22px,var(--ink) 22px 44px)}
.hg{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:center;padding:50px 0 80px}.hg>*{min-width:0}
.hero h1{font-size:clamp(64px,9vw,130px)}.hero h1 span{color:var(--yl)}.hero p{font-size:20px;color:#D5DEFA;max-width:28em;margin:10px 0 24px}
.hero img{width:100%;aspect-ratio:4/3;object-fit:cover;border:6px solid var(--yl)}
.btn{display:inline-block;background:var(--yl);color:var(--ink);text-decoration:none;font:600 17px var(--b);padding:14px 24px;border:0;cursor:pointer}.btn.d{background:var(--ink);color:#fff}
.row{display:flex;gap:12px;flex-wrap:wrap}
.open{display:inline-flex;gap:8px;align-items:center;background:rgba(0,0,0,.2);padding:6px 12px;margin-top:18px;font-size:15px}.open i{width:10px;height:10px;border-radius:50%;background:#22C55E}.open i.c{background:#EF4444}
section{padding:80px 0}.sh{max-width:680px;margin-bottom:26px}.sh h2{font-size:clamp(50px,6.4vw,86px);color:var(--rb2)}.sh p{color:var(--gr);margin:6px 0 0}
.pl{background:#fff;border:2px solid var(--ink)}.pl .r{display:grid;grid-template-columns:1fr auto auto;gap:20px;align-items:center;padding:16px 20px;border-bottom:1px solid var(--ln)}.pl .r:last-child{border-bottom:0}
.pl h3{font-family:var(--b);font-weight:600;font-size:18px;text-transform:none;letter-spacing:0}.pl p{margin:2px 0 0;color:var(--gr);font-size:15px}.pl .t{color:var(--gr);font-size:15px;white-space:nowrap}.pl .p{font-family:var(--h);font-size:30px;white-space:nowrap}
.bk{background:var(--ink);color:#fff}.bk .sh h2{color:var(--yl)}.bk .sh p{color:#B5BAC6}.bg{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:start}.bg>*{min-width:0}
.bf{background:#fff;color:var(--ink);padding:26px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
.bf label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}.bf input,.bf select{width:100%;font:16px var(--b);padding:11px;border:2px solid var(--ln);margin-bottom:14px;color:var(--ink);background:#fff}
.sz{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:14px}.sz label{position:relative;margin:0;cursor:pointer}.sz input{position:absolute;opacity:0;width:1px;height:1px;left:0;top:0;margin:0}.sz span{display:block;border:2px solid var(--ln);padding:10px 4px;text-align:center;font-size:14px;font-weight:600}.sz span svg{display:block;margin:0 auto 4px}.sz input:checked+span{border-color:var(--rb);background:#E7EDFF}.sz input:focus-visible+span{outline:3px solid var(--yl)}
.est{background:var(--yl);color:var(--ink);padding:24px;position:sticky;top:16px}.est h3{font-size:34px}.est .big{font-family:var(--h);font-size:64px;line-height:1;margin:10px 0}.est ul{padding-left:18px;margin:10px 0 0}
.msg{visibility:hidden;margin:12px 0 0;font-weight:600;color:var(--rb2)}.msg.on{visibility:visible}
.rv{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.rv blockquote{margin:0;background:#fff;padding:22px;border-left:6px solid var(--rb)}.rv .s{color:#D97706;letter-spacing:2px}.rv p{margin:8px 0}.rv cite{font-style:normal;color:var(--gr);font-size:15px}
footer{background:var(--rb2);color:#C7D2F5;padding:26px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hg,.bg{grid-template-columns:1fr}.rv{grid-template-columns:1fr}.est{position:static}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:76px;left:0;right:0;background:var(--rb2);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.pl .r{grid-template-columns:1fr auto}.pl .t{grid-column:1;grid-row:2}.fr{grid-template-columns:1fr}.sz{grid-template-columns:1fr 1fr}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const n=new Date(),h=n.getHours()+n.getMinutes()/60,d=n.getDay(),o=(d>=1&&d<=5&&h>=8&&h<18)||(d===6&&h>=8.5&&h<13);$('od').classList.toggle('c',!o);$('ot').textContent=o?'Open now. Mon to Fri 8am to 6pm, Sat 8:30am to 1pm':'Closed now. Mon to Fri 8am to 6pm, Sat 8:30am to 1pm';
const S=[["MOT test","Includes free retest within 10 days",54.85,"1 hour",0],["Interim service","Oil, filter and 40 point check",119,"1.5 hours",1],["Full service","Oil, all filters, plugs and 70 point check",219,"3 hours",1],["Front brake pads","Pads fitted, discs checked",145,"1.5 hours",1],["Air con re-gas","Clean and re-gas, leak test",69,"45 minutes",1],["Clutch replacement","Kit, labour and test drive",620,"1 day",1],["Diagnostic check","Warning light scan and report",45,"45 minutes",0]];
$('pl').innerHTML=S.map(s=>`<div class="r"><div><h3>${s[0]}</h3><p>${s[1]}</p></div><span class="t">${s[3]}</span><span class="p">£${s[2]%1?s[2].toFixed(2):s[2]}</span></div>`).join('');
$('sv').innerHTML=S.map((s,i)=>`<option value="${i}" ${i===2?'selected':''}>${s[0]}</option>`).join('');const Y=new Date().getFullYear();$('yr2').innerHTML=Array.from({length:20},(_,i)=>`<option>${Y-i}</option>`).join('');$('yr2').value=Y-6;
function est(){const s=S[+$('sv').value],m=s[4]?+document.querySelector('input[name=sz]:checked').value:1,age=Y-+$('yr2').value,old=s[4]&&age>12?1.08:1,p=s[2]*m*old;
$('en').textContent=s[0];$('ep').textContent='£'+(p%1?p.toFixed(2):Math.round(p));$('et').textContent=`About ${s[3]} in the workshop`;
$('el').innerHTML=`<li>${s[1]}</li>${m>1?'<li>Price includes larger vehicle parts</li>':''}${old>1?'<li>Cars over 12 years may need extra parts, we will call first</li>':''}<li>Free courtesy car if booked 3 days ahead</li>`}
$('bf').addEventListener('change',est);est();let bd=new Date(Date.now()+2*864e5);if(bd.getDay()===0)bd=new Date(bd.getTime()+864e5);$('bd').value=bd.toISOString().slice(0,10);$('bd').min=new Date().toISOString().slice(0,10);
$('bf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Booked: ${S[+$('sv').value][0]} on ${$('bd').value}. Drop the keys at reception by 8:30am. We'll text ${$('bp').value} when it's ready.`;$('msg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
